<?php

namespace Database\Seeders;

use App\Models\Prophet;
use App\Models\StoryChapter;
use App\Models\ReflectionQuestion;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class ProphetStorySeeder extends Seeder
{
    public function run(): void
    {
        DB::statement('SET FOREIGN_KEY_CHECKS=0;');
        ReflectionQuestion::truncate();
        StoryChapter::truncate();
        Prophet::truncate();
        DB::statement('SET FOREIGN_KEY_CHECKS=1;');

        $stories = $this->getStoriesData();

        foreach ($stories as $order => $pData) {
            $prophet = Prophet::create([
                'name' => $pData['name'],
                'name_arabic' => $pData['name_arabic'],
                'short_intro' => $pData['short_intro'],
                'cover_image_path' => $pData['cover_image_path'] ?? '',
                'chronological_order' => $order + 1,
            ]);

            foreach ($pData['chapters'] as $chIndex => $cData) {
                $chapter = StoryChapter::create([
                    'prophet_id' => $prophet->id,
                    'chapter_number' => $chIndex + 1,
                    'title' => $cData['title'],
                    'content_standard' => $cData['content_standard'],
                    'content_kid_friendly' => $cData['content_kid_friendly'],
                    'moral_lesson' => $cData['moral_lesson'],
                    'source_reference' => $cData['source_reference'],
                ]);

                if (!empty($cData['reflection_questions'])) {
                    foreach ($cData['reflection_questions'] as $qIndex => $qData) {
                        ReflectionQuestion::create([
                            'story_chapter_id' => $chapter->id,
                            'question' => $qData['question'],
                            'answer_hint' => $qData['answer_hint'] ?? null,
                            'sort_order' => $qIndex + 1,
                        ]);
                    }
                }
            }
        }
    }

